import React from 'react';
import { ArrowDown } from '@hexa-ui/icons';
import { render, screen, fireEvent } from '@testing-library/react';
import Button from './Button';

describe('Button', () => {
  describe('Primary (default)', () => {
    test('should render without crashing with default size (medium)', () => {
      render(<Button />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with small size prop', () => {
      render(<Button size="small" className="styled-class" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with large size prop', () => {
      render(<Button size="large" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with no size prop given', () => {
      render(<Button variant="primary" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with elevated prop', () => {
      render(<Button size="large" elevated />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should be clickable', () => {
      const mockedFunction = jest.fn();

      render(<Button onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).toBeCalled();
    });

    test('should not be clickable when disabled prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button disabled onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });

    test('should not be clickable when isLoading prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button isLoading onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });

    test('should render without crashing with leading prop', () => {
      render(<Button variant="primary" size="small" leading icon={ArrowDown} />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with traling prop', () => {
      render(<Button variant="primary" size="small" trailing icon={ArrowDown} />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with isLoading prop', () => {
      render(<Button variant="primary" size="small" isLoading />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });
  });

  describe('Secondary', () => {
    test('should render without crashing with small size prop', () => {
      render(<Button variant="secondary" size="small" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with medium size prop', () => {
      render(<Button variant="secondary" size="medium" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with large size prop', () => {
      render(<Button variant="secondary" size="large" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with no size prop given', () => {
      render(<Button variant="secondary" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with elevated prop as true', () => {
      render(<Button variant="secondary" elevated />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should be clickable', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="secondary" onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).toBeCalled();
    });

    test('should not be clickable when disabled prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="secondary" disabled onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });

    test('should not be clickable when isLoading prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="secondary" isLoading onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });
  });

  describe('Destructive', () => {
    test('should render without crashing with small size prop', () => {
      render(<Button variant="destructive" size="small" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with medium size prop', () => {
      render(<Button variant="destructive" size="medium" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with large size prop', () => {
      render(<Button variant="destructive" size="large" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with no size prop given', () => {
      render(<Button variant="destructive" />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should render without crashing with elevated prop as true', () => {
      render(<Button variant="destructive" elevated />);

      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    test('should be clickable', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="destructive" onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).toBeCalled();
    });

    test('should not be clickable when disabled prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="destructive" disabled onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });

    test('should not be clickable when isLoading prop is true', () => {
      const mockedFunction = jest.fn();

      render(<Button variant="destructive" isLoading onClick={mockedFunction} />);

      fireEvent.click(screen.getByRole('button'));

      expect(mockedFunction).not.toBeCalled();
    });
  });
});
